INSERT INTO pista (id_desafio, orden_pista, contenido) VALUES
  (1, 1, 'Las filas son horizontales y se cuentan de arriba hacia abajo empezando en 0.'),
  (1, 2, 'Las columnas son verticales y se cuentan de izquierda a derecha empezando en 0.'),
  (1, 3, 'Busca el número 2 a la izquierda del tablero y el 3 arriba: la obra va donde se cruzan.'),
  (2, 1, 'El primer número entre corchetes siempre es la fila.'),
  (2, 2, 'Fila 4 es la quinta fila porque empezamos a contar en 0.'),
  (2, 3, 'Baja hasta la fila 4 y avanza solo una columna desde la izquierda.'),
  (3, 1, 'Recorrer una fila es mantener el índice de la fila fijo y mover la columna.'),
  (3, 2, 'Empieza en matriz[1][0] y termina en matriz[1][5].'),
  (3, 3, 'El orden importa: 0, 1, 2, 3, 4, 5. La columna 6 no hace parte del recorrido.'),
  (4, 1, 'Ahora la columna se queda fija y es la fila la que avanza.'),
  (4, 2, 'Empieza arriba, en la fila 0, y baja una fila cada vez.'),
  (4, 3, 'Son 7 celdas: matriz[0][3], matriz[1][3] ... hasta matriz[6][3].'),
  (5, 1, 'matriz[0].length es el número de columnas de la galería.'),
  (5, 2, 'Dentro del for solo necesitas una instrucción: colocar(...).'),
  (5, 3, 'La solución es: colocar(fila, columna); dentro del ciclo.'),
  (6, 1, 'Fija la columna en tu código: si la misión es recorrer la columna 4, la posición siempre debe verse como matriz[fila][4].'),
  (6, 2, 'Para saber si un número es par, su residuo al dividirlo entre 2 debe ser cero. En Java se usa el operador módulo (%).'),
  (6, 3, 'Construye una condición así: if (fila % 2 == 0) { colocar(fila, columna); }'),
  (7, 1, 'Necesitas dos ciclos for: uno para las filas y otro, dentro, para las columnas.'),
  (7, 2, 'La última fila es matriz.length - 1 y la última columna es matriz[0].length - 1.'),
  (7, 3, 'Una celda está en el borde si fila == 0 || fila == matriz.length - 1 || columna == 0 || columna == matriz[0].length - 1.'),
  (8, 1, 'Recuerda que 0 también es múltiplo de 2.'),
  (8, 2, 'Necesitas que se cumplan dos condiciones al mismo tiempo: usa el operador &&.'),
  (8, 3, 'La condición es: if (fila % 2 == 0 && columna % 2 == 0).');
INSERT INTO mensaje_curi (id_desafio, tipo, contenido, condicion_activacion) VALUES
  (1, 'INTRO', '¡Bienvenido a la Sala de Iniciación! Recuerda: primero la fila, después la columna.', NULL),
  (1, 'EXITO', '¡Perfecto! matriz[2][3] es exactamente la fila 2 y la columna 3.', NULL),
  (1, 'ERROR', 'Esa no es la posición. Revisa los números del borde: fila 2, columna 3.', 'POSICION_INCORRECTA'),
  (2, 'INTRO', 'Muy bien, ya conoces los índices. Leamos esta posición: matriz[4][1].', NULL),
  (2, 'EXITO', '¡Lo lograste! Ya lees posiciones como un programador.', NULL),
  (2, 'ERROR', 'Casi. ¿Intercambiaste la fila con la columna? matriz[fila][columna].', 'POSICION_INCORRECTA'),
  (3, 'INTRO', 'En esta sala recorremos filas: la fila no cambia, la columna avanza.', NULL),
  (3, 'EXITO', '¡Así se recorre una fila! En código sería un for sobre las columnas.', NULL),
  (3, 'ERROR', 'El recorrido se desvió. Mira la celda marcada en rojo y vuelve a intentarlo.', 'ORDEN_INCORRECTO'),
  (4, 'INTRO', 'Ahora al revés: la columna se queda quieta y bajamos fila por fila.', NULL),
  (4, 'EXITO', '¡Columna completa! Ya dominas filas y columnas.', NULL),
  (4, 'ERROR', 'Ese paso no sigue la columna 3 hacia abajo. Revisa la celda en rojo.', 'ORDEN_INCORRECTO'),
  (5, 'INTRO', '¡Subimos de nivel! Ahora le darás órdenes a la galería escribiendo código Java.', NULL),
  (5, 'EXITO', '¡Tu primer programa funciona! Mira cómo el ciclo recorrió la fila.', NULL),
  (5, 'ERROR', 'El programa no colocó las obras esperadas. Revisa la consola y la matriz de pinturas.', 'RESULTADO_INCORRECTO'),
  (6, 'INTRO', 'Ahora no basta con recorrer: hay que decidir dónde colocar cada obra.', NULL),
  (6, 'EXITO', '¡Excelente! El operador % es tu nuevo superpoder.', NULL),
  (6, 'ERROR', 'Algunas obras quedaron en filas impares o faltaron filas pares.', 'RESULTADO_INCORRECTO'),
  (7, 'INTRO', '¡Alerta! Protejamos las obras rodeando la estantería por sus bordes.', NULL),
  (7, 'EXITO', '¡Galería protegida! El ladrón no podrá pasar por el perímetro.', NULL),
  (7, 'ERROR', 'Quedaron huecos en el borde o pusiste obras en el centro.', 'RESULTADO_INCORRECTO'),
  (8, 'INTRO', 'Exposición Maestra: este es el último reto de la galería. ¡Tú puedes!', NULL),
  (8, 'EXITO', '¡Exposición completada! Eres oficialmente un maestro de las matrices.', NULL),
  (8, 'ERROR', 'Revisa las dos condiciones: fila y columna deben ser múltiplos de 2.', 'RESULTADO_INCORRECTO');
